CREATE TABLE IF NOT EXISTS app_org (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, type VARCHAR(20) NOT NULL, parent_id BIGINT, contact_person VARCHAR(100), phone VARCHAR(30), enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS app_role (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, permissions VARCHAR(4000) NOT NULL);
CREATE TABLE IF NOT EXISTS app_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL, org_id BIGINT NOT NULL, phone VARCHAR(30), email VARCHAR(100), enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS app_dict (id BIGINT AUTO_INCREMENT PRIMARY KEY, type VARCHAR(50) NOT NULL, code VARCHAR(50) NOT NULL, label VARCHAR(100) NOT NULL, sort_order INT DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(type,code));
CREATE TABLE IF NOT EXISTS app_menu (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, path VARCHAR(100) NOT NULL, icon VARCHAR(50), permission VARCHAR(50), parent_id BIGINT, sort_order INT DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS insurance_plan (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, rate_a DECIMAL(6,4) NOT NULL, rate_b DECIMAL(6,4) NOT NULL, rate_c DECIMAL(6,4) NOT NULL, description VARCHAR(1000), enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS surgery (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, category VARCHAR(100), price DECIMAL(14,2) NOT NULL, description VARCHAR(1000), enabled BOOLEAN NOT NULL DEFAULT TRUE, CHECK(price >= 0));
CREATE TABLE IF NOT EXISTS patient (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, gender VARCHAR(10) NOT NULL, birth_date DATE, phone VARCHAR(30), id_number VARCHAR(30) NOT NULL UNIQUE, card_no VARCHAR(50) NOT NULL UNIQUE, address VARCHAR(300), plan_id BIGINT NOT NULL, balance DECIMAL(14,2) NOT NULL DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT TRUE, CHECK(balance >= 0));
CREATE TABLE IF NOT EXISTS medical_visit (id BIGINT AUTO_INCREMENT PRIMARY KEY, visit_no VARCHAR(50) NOT NULL UNIQUE, patient_id BIGINT NOT NULL, doctor_id BIGINT NOT NULL, plan_id BIGINT NOT NULL, patient_name VARCHAR(100) NOT NULL, card_no VARCHAR(50) NOT NULL, doctor_name VARCHAR(100) NOT NULL, plan_name VARCHAR(100) NOT NULL, outpatient_type VARCHAR(5) NOT NULL, diagnosis VARCHAR(2000) NOT NULL, diagnosis_fee DECIMAL(14,2) NOT NULL, surgery_fee DECIMAL(14,2) NOT NULL, total_amount DECIMAL(14,2) NOT NULL, reimbursement_rate DECIMAL(6,4) NOT NULL, self_pay_amount DECIMAL(14,2) NOT NULL, claim_amount DECIMAL(14,2) NOT NULL, audit_status VARCHAR(20) NOT NULL, payment_status VARCHAR(30) NOT NULL, reject_reason VARCHAR(1000), outstanding_amount DECIMAL(14,2) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, reviewed_at TIMESTAMP, CHECK(outstanding_amount >= 0));
CREATE TABLE IF NOT EXISTS visit_item (id BIGINT AUTO_INCREMENT PRIMARY KEY, visit_id BIGINT NOT NULL, surgery_id BIGINT NOT NULL, surgery_name VARCHAR(100) NOT NULL, unit_price DECIMAL(14,2) NOT NULL, quantity INT NOT NULL, subtotal DECIMAL(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS audit_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, visit_id BIGINT NOT NULL, reviewer_id BIGINT NOT NULL, decision VARCHAR(20) NOT NULL, reason VARCHAR(1000), reviewer_name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL, UNIQUE(visit_id));
CREATE TABLE IF NOT EXISTS card_transaction (id BIGINT AUTO_INCREMENT PRIMARY KEY, patient_id BIGINT NOT NULL, patient_name VARCHAR(100) NOT NULL, card_no VARCHAR(50) NOT NULL, type VARCHAR(30) NOT NULL, amount DECIMAL(14,2) NOT NULL, balance_after DECIMAL(14,2) NOT NULL, business_no VARCHAR(50) NOT NULL, note VARCHAR(1000), operator_name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL, CHECK(balance_after >= 0));
CREATE TABLE IF NOT EXISTS request_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, request_id VARCHAR(50) NOT NULL UNIQUE, action VARCHAR(50) NOT NULL, fingerprint VARCHAR(64) NOT NULL, user_id BIGINT NOT NULL, business_id BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_session (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS app_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50), action VARCHAR(50) NOT NULL, target VARCHAR(200), detail VARCHAR(2000), ip VARCHAR(100), created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS app_file (id BIGINT AUTO_INCREMENT PRIMARY KEY, uploader_id BIGINT NOT NULL, original_name VARCHAR(255) NOT NULL, storage_name VARCHAR(100) NOT NULL UNIQUE, content_type VARCHAR(100) NOT NULL, uploader_name VARCHAR(100) NOT NULL, size BIGINT NOT NULL, created_at TIMESTAMP NOT NULL);
